constexpr auto PIPE_IN_BUFFER_SIZE = 4096;
constexpr auto PIPE_OUT_BUFFER_SIZE = 4096;
constexpr auto PIPE_READ_TIMEOUT = 1000;

void CreatePipe() {
    SECURITY_ATTRIBUTES sa;
    sa.nLength = sizeof(sa);
    sa.lpSecurityDescriptor = NULL;
    sa.bInheritHandle = TRUE;

    // Create a pipe with the given name and properties.
    HANDLE hPipe = CreateNamedPipeA(
        PIPE_NAME,
        PIPE_ACCESS_DUPLEX,
        PIPE_TYPE_MESSAGE | PIPE_READMODE_MESSAGE | PIPE_WAIT,
        PIPE_MAX_INSTANCES,
        PIPE_IN_BUFFER_SIZE,
        PIPE_OUT_BUFFER_SIZE,
        NMPWAIT_USE_DEFAULT_WAIT,
        &sa
    );

    if (hPipe == INVALID_HANDLE_VALUE) {
        std::cerr << "CreateNamedPipe failed with error code: " << GetLastError() << std::endl;
        return;
    }

    std::cout << "Pipe created: " << PIPE_NAME << std::endl;
}

void WriteToPipe(HANDLE hPipe, const std::string& data) {
    OVERLAPPED overlapped = { 0 };
    DWORD bytesWritten = 0;

    // Write data to the pipe.
    BOOL writeResult = WriteFile(hPipe, data.c_str(), data.length(), &bytesWritten, &overlapped);

    if (!writeResult || bytesWritten == 0) {
        std::cerr << "WriteFile failed with error code: " << GetLastError() << std::endl;
        return;
    }

    std::cout << "Wrote " << bytesWritten << " bytes to pipe." << std::endl;
}

void ReadFromPipe(HANDLE hPipe) {
    CHAR buffer[PIPE_IN_BUFFER_SIZE];
    DWORD bytesRead = 0;
    DWORD totalBytesRead = 0;
    OVERLAPPED overlapped = { 0 };

    while (true) {
        ZeroMemory(buffer, PIPE_IN_BUFFER_SIZE);

        // Read data from the pipe.
        BOOL readResult = ReadFile(hPipe, buffer, PIPE_IN_BUFFER_SIZE - 1, &bytesRead, &overlapped);

        if (!readResult || bytesRead == 0) {
            if (GetLastError() != ERROR_IO_PENDING) {
                std::cerr << "ReadFile failed with error code: " << GetLastError() << std::endl;
                break;
            }

            continue;
        }

        totalBytesRead += bytesRead;
        buffer[bytesRead] = '\0';
        std::cout << "Read " << bytesRead << " bytes from pipe: " << buffer << std::endl;

        if (totalBytesRead >= PIPE_IN_BUFFER_SIZE) {
            std::cout << "Received complete file." << std::endl;
            break;
        }
    }
}

int main() {
    CreatePipe();

    // Open the pipe for reading and writing.
    HANDLE hPipe = CreateFileA(PIPE_NAME, GENERIC_READ | GENERIC_WRITE, 0, NULL, OPEN_EXISTING, 0, NULL);

    if (hPipe == INVALID_HANDLE_VALUE) {
        std::cerr << "CreateFile failed with error code: " << GetLastError() << std::endl;
        return 1;
    }

    std::string data = "Hello, World!";
    WriteToPipe(hPipe, data);

    ReadFromPipe(hPipe);

    CloseHandle(hPipe);

    return 0;
}
```

To compile the program, use a C++ compiler that supports the Windows API, such as Visual Studio or MinGW.

This example creates a named pipe, writes a simple string to it, and reads the data back from the pipe. You can modify the `WriteToPipe` function to read a file and write its contents to the pipe, and modify the `ReadFromPipe` function to write the received data to a file.

To transfer files between processes, you would need to create a separate process that opens the pipe for reading and writing, reads the data from the pipe, and saves it to a file. The main process would open the pipe, write the file contents to the pipe, and then close the pipe.

