    std::ifstream file(fileName, std::ios::binary | std::ios::ate);
    if (!file.is_open()) {
        std::cerr << "Error: Could not open file." << std::endl;
        exit(1);
    }

    size_t fileSize = static_cast<size_t>(file.tellg());
    std::vector<BYTE> buffer(fileSize);
    file.seekg(0);
    file.read(reinterpret_cast<char*>(buffer.data()), fileSize);
    file.close();

    return buffer;
}

void WriteMemory(LPVOID lpBaseAddress, const std::vector<BYTE>& buffer) {
    SIZE_T written;
    WriteProcessMemory(GetCurrentProcess(), lpBaseAddress, buffer.data(), buffer.size(), &written);
}

void CreateRemoteThread(LPVOID lpThreadAddress, LPVOID lpParameter, DWORD dwCreationFlags, LPTHREAD_START_ROUTINE lpStartAddress, LPVOID lpThreadId) {
    CreateRemoteThread(GetCurrentProcess(), NULL, 0, lpStartAddress, lpParameter, 0, lpThreadId);
}

void InjectDLL() {
    const std::string dllPath = "path/to/your/dll.dll";
    std::vector<BYTE> dllBytes = ReadFileToMemory(dllPath);

    // Calculate the size of the DLL header and the RVA of the DLL's entry point
    IMAGE_DOS_HEADER dosHeader;
    IMAGE_NT_HEADERS32 ntHeaders;
    memcpy(&dosHeader, dllBytes.data(), sizeof(dosHeader));
    memcpy(&ntHeaders, reinterpret_cast<LPBYTE>(dllBytes.data()) + dosHeader.e_lfanew, sizeof(ntHeaders));

