FILEINTEGRITYCHECK_API bool CheckFileIntegrity(const std::wstring& filePath) {
    HANDLE fileHandle = CreateFileW(filePath.c_str(), GENERIC_READ, FILE_SHARE_READ, nullptr, OPEN_EXISTING, FILE_ATTRIBUTE_NORMAL, nullptr);
    if (fileHandle == INVALID_HANDLE_VALUE) {
        return false;
    }

    DWORD fileSizeHigh = 0;
    DWORD fileSizeLow = GetFileSizeEx(fileHandle, reinterpret_cast<LPDWORD>(&fileSizeHigh));
    CloseHandle(fileHandle);

    std::vector<char> fileContent(fileSizeLow);
    ReadFile(fileHandle, fileContent.data(), fileSizeLow, nullptr, nullptr);

    SHA256_CTX ctx;
    SHA256_Init(&ctx);
    SHA256_Update(&ctx, fileContent.data(), fileSizeLow);
    SHA256_Final(reinterpret_cast<unsigned char*>(fileContent.data()), &ctx);

    // Compare the calculated hash with the expected hash.
