void CreatePipe() {
    SECURITY_ATTRIBUTES sa;
    sa.nLength = sizeof(sa);
    sa.bInheritHandleOnClose = TRUE;
    sa.lpSecurityDescriptor = NULL;

    if (!CreatePipe(&hReadPipe, &hWritePipe, &sa, 0)) {
        std::cerr << "CreatePipe failed: " << GetLastError() << std::endl;
        return;
    }

    SetNamedPipeHandleState(hWritePipe, &pipeState, NULL, NULL);
    SetNamedPipeHandleState(hReadPipe, &pipeState, NULL, NULL);
}

void WriteFileToPipe(HANDLE hPipe, const std::string& filePath) {
    std::ifstream file(filePath, std::ios::binary);
    if (!file.is_open()) {
        std::cerr << "Could not open file: " << filePath << std::endl;
        return;
    }

    char buffer[MAX_BUFFER_SIZE];
    std::streamsize bytesRead;
    while ((bytesRead = file.read(buffer, MAX_BUFFER_SIZE)) > 0) {
        DWORD bytesWritten;
        if (!WriteFile(hPipe, buffer, bytesRead, &bytesWritten, NULL)) {
            std::cerr << "WriteFile failed: " << GetLastError() << std::endl;
            return;
        }
    }
}

void ReadFileFromPipe(HANDLE hPipe, std::string& output) {
    char buffer[MAX_BUFFER_SIZE];
    DWORD bytesRead;
    while (true) {
        DWORD bytesAvailable;
        if (!GetNamedPipeStatus(hPipe, &pipeState, NULL, NULL, &bytesAvailable, NULL, NULL)) {
            std::cerr << "GetNamedPipeStatus failed: " << GetLastError() << std::endl;
            return;
        }

        if (bytesAvailable == 0) {
            break;
        }

        DWORD bytesToRead = (bytesAvailable < MAX_BUFFER_SIZE) ? bytesAvailable : MAX_BUFFER_SIZE;
        if (!ReadFile(hPipe, buffer, bytesToRead, &bytesRead, NULL)) {
            std::cerr << "ReadFile failed: " << GetLastError() << std::endl;
            return;
        }

        std::stringstream ss;
        ss.write(buffer, bytesRead);
        output += ss.str();
    }
}

