import dns.resolver

def get_subdomains_and_ips(domain):
    answers = []
    for label in dns.resolver.query(domain, 'MX', rd=True):
        answers.append((label.exchange, label.preference))

    for answer in dns.resolver.query(domain, 'NS', rd=True):
        for subdomain in dns.resolver.query(answer.target, 'TXT', rd=True):
            if 'google-site-verification' in str(subdomain.target):
                continue
            if 'mail' in str(subdomain.target):
                continue
            if 'www' in str(subdomain.target):
                continue
            for ip in dns.resolver.query(subdomain.target, 'A', rd=True):
                answers.append((subdomain.target, ip.address))

    return answers

if __name__ == "__main__":
    domain = input("Enter the domain: ")
    results = get_subdomains_and_ips(domain)
    print(f"Subdomains and their IP addresses: {results}")
```

This script filters out common subdomains like `mail` and `www` to avoid unnecessary queries. It also skips subdomains that have Google Site Verification TXT records, which are often used for website ownership verification. You can customize the filtering as needed for your specific use case.

Please note that this script does not perform any error handling or rate limiting, so it may not work well for large-scale queries or sensitive domains. Also, it only queries for A records, so other types of DNS records (like CNAME, MX, etc.) will not be included.

