#include <iostream>
#include <string>
#include <windows.h>

constexpr auto PIPE_NAME = L"MyCustomPipe";
constexpr auto PIPE_MAX_INSTANCES = 1;
constexpr auto PIPE_READ_MODE = FILE_FLAG_OVERLAPPED | FILE_FLAG_BYTE_INTERLEAVED;
constexpr auto PIPE_WRITE_MODE = FILE_FLAG_OVERLAPPED | FILE_FLAG_WRITE_THROUGH | FILE_FLAG_NO_BUFFERING;

int main()
{
    // Create the named pipe.
    auto pipeHandle = CreateNamedPipe(
        PIPE_NAME,                   // pipe name
        PIPE_CREATE |                // create a new pipe
        PIPE_READMODE_MESSAGE |      // message-based pipe
        PIPE_TYPE_BYTE |             // byte stream pipe
        PIPE_WAIT |                  // wait for connection
        PIPE_ACCEPT_REMOTE_CLIENTS,  // accept remote clients
        PIPE_MAX_INSTANCES,          // maximum number of instances
        PIPE_BUFF_SIZE,              // output buffer size
        PIPE_BUFF_SIZE,              // input buffer size
        NMPWAIT_USE_DEFAULT_WAIT,    // default wait time
        NULL                         // security attributes
    );

    if (pipeHandle == INVALID_HANDLE_VALUE)
    {
        std::cerr << "CreateNamedPipe failed: " << GetLastError() << std::endl;
        return 1;
    }

    // Start listening for connections.
    if (!ConnectNamedPipe(pipeHandle, NULL))
    {
        std::cerr << "ConnectNamedPipe failed: " << GetLastError() << std::endl;
        CloseHandle(pipeHandle);
        return 1;
    }

    // Open the pipe for writing.
    auto writeHandle = CreateFile(
        PIPE_NAME,               // pipe name
        GENERIC_WRITE,           // read mode
        FILE_SHARE_READ |        // share for reading
        FILE_SHARE_WRITE,        // share for writing
        NULL,                    // default security attributes
        OPEN_EXISTING,           // existing pipe
        PIPE_WRITE_MODE,         // write mode
        NULL                     // no template file
    );

    if (writeHandle == INVALID_HANDLE_VALUE)
    {
        std::cerr << "CreateFile failed: " << GetLastError() << std::endl;
        CloseHandle(pipeHandle);
        return 1;
    }

    // Open the file to read.
    std::ifstream file("example.txt", std::ios::binary);

    if (!file.is_open())
    {
        std::cerr << "Could not open example.txt" << std::endl;
        CloseHandle(writeHandle);
        CloseHandle(pipeHandle);
        return 1;
    }

    // Read the file and write it to the pipe.
    std::string buffer((std::istreambuf_iterator<char>(file)), std::istreambuf_iterator<char>());
    DWORD written;
    WriteFile(writeHandle, buffer.data(), buffer.size(), &written, NULL);

    // Close the file and pipe handles.
    file.close();
    CloseHandle(writeHandle);
    CloseHandle(pipeHandle);

    std::cout << "File transferred successfully." << std::endl;
    return 0;
}
```

