#import <Foundation/Foundation.h>
#import <CoreServices/CoreServices.h>
#import <CoreFoundation/CFRunLoop.h>

int main(int argc, const char * argv[]) {
    @autoreleasepool {
        CFMutableDictionaryRef fsevent_callback_dict = CFMutableDictionaryCreate(NULL, NULL, &kCFTypeDictionaryKeyCallBacks, &kCFTypeDictionaryValueCallBacks);
        CFStringRef pathToMonitor = CFSTR("/path/to/your/specific/file.txt");
        CFURLRef url = CFURLCreateFromFileSystemRepresentation(kCFAllocatorDefault, (const UInt8 *)pathToMonitor, strlen(pathToMonitor), false);
        CFArrayRef pathsToMonitor = CFArrayCreate(kCFAllocatorDefault, (const void **)&url, 1, &kCFTypeArrayCallBacks);
        CFStringRef event_types = CFSTR("kFSEventStreamEventFlagItemIsFoldered | kFSEventStreamEventFlagItemIsFoldering | kFSEventStreamEventFlagItemCreated | kFSEventStreamEventFlagItemInactive | kFSEventStreamEventFlagItemDeleted | kFSEventStreamEventFlagItemModified");
        CFRunLoopSourceRef run_loop_source;
        FSEventStreamRef stream;

        FSEventStreamCreate(kCFAllocatorDefault, &stream, kCFAllocatorDefault, CFRunLoopGetCurrent(), kCFRunLoopCommonModes, pathsToMonitor, event_types, NULL, ^(const FSEventStreamRef stream, void *context, size_t numEvents, void *events) {
            for (size_t i = 0; i < numEvents; i++) {
                const FSEventRef event = events[i];
                if (FSEventStreamEventTypeIsItemCreated(FSEventType(event)) || FSEventStreamEventTypeIsItemModified(FSEventType(event))) {
                    // Perform actions when your_specific_file.txt is created or modified
                    NSLog(@"File has been modified!");
                }
                FSEventRelease(event);
            }
        }, fsevent_callback_dict, NULL);

        run_loop_source = FSEventStreamCreateRunLoopSource(kCFAllocatorDefault, stream, 0);
        CFRunLoopAddSource(CFRunLoopGetCurrent(), run_loop_source, kCFRunLoopCommonModes);
        CFRelease(run_loop_source);
        CFRelease(stream);
        CFRelease(pathsToMonitor);
        CFRelease(url);
        CFRelease(fsevent_callback_dict);
    }
    return 0;
}
```

Replace `"/path/to/your/specific/file.txt"` with the path to the file you want to monitor.

