```javascript
// signaling-server.js
const express = require('express');
const app = express();
const http = require('http').Server(app);
const io = require('socket.io')(http);

app.get('/', (req, res) => {
  res.sendFile(__dirname + '/index.html');
});

io.on('connection', (socket) => {
  socket.on('join', (roomId) => {
    socket.join(roomId);
  });

  socket.on('offer', (data) => {
    socket.to(data.target).emit('offer', { sdp: data.sdp, sender: socket.id });
  });

  socket.on('answer', (data) => {
    socket.to(data.sender).emit('answer', { sdp: data.sdp });
  });
});

http.listen(3000, () => {
  console.log('Signaling server listening on *:3000');
});
```

2. Next, let's create the HTML file with JavaScript to handle the WebRTC connection:

```html
