<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>WebRTC P2P Communication</title>
  <script src="/socket.io/socket.io.js"></script>
</head>
<body>
  <h1>WebRTC P2P Communication</h1>
  <video id="localVideo" autoplay muted></video>
  <video id="remoteVideo" autoplay></video>

  <script>
    const socket = io();
    const localVideo = document.getElementById('localVideo');
    const remoteVideo = document.getElementById('remoteVideo');
    const pcConfig = {'iceServers': [{'urls': 'stun:stun.l.google.com:19302'}]};

    const pc = new RTCPeerConnection(pcConfig);

    pc.onicecandidate = (event) => {
      if (event.candidate) {
        socket.emit('icecandidate', { target: 'otherUser', candidate: event.candidate });
      }
    };

    pc.onaddstream = (event) => {
      remoteVideo.srcObject = event.stream;
    };

    socket.on('offer', (data) => {
      pc.setRemoteDescription(new RTCSessionDescription(data.sdp))
        .then(() => pc.createAnswer())
        .then(answer => pc.setLocalDescription(answer))
        .then(() => socket.emit('answer', { target: data.sender, sdp: pc.localDescription }));
    });

    socket.on('answer', (data) => {
      pc.setRemoteDescription(new RTCSessionDescription(data.sdp));
    });

    socket.on('icecandidate', (data) => {
      if (data.candidate) {
        pc.addIceCandidate(new RTCIceCandidate(data.candidate));
      }
    });

    navigator.mediaDevices.getUserMedia({ video: true, audio: true })
      .then(stream => {
        localVideo.srcObject = stream;
        pc.addStream(stream);
      });

    const createOffer = () => {
      pc.createOffer()
        .then(offer => pc.setLocalDescription(offer))
        .then(() => socket.emit('offer', { target: 'otherUser', sdp: pc.localDescription }));
    };

