def read_chrome_history(file_path):
    with open(file_path, 'r') as f:
        lines = f.readlines()

    history = []
    current_url = None

    for line in lines:
        if line.startswith('url'):
            current_url = line.split(':')[1].strip()
        elif line.startswith('"visits"):
            visit_data = line.split(':')[1].strip().split(',')
            visit_count = int(visit_data[1].strip('[]'))
            history.append((current_url, visit_count))

    return history

def analyze_browser_history(history):
    urls_dict = {}

    for url, count in history:
        if url not in urls_dict:
            urls_dict[url] = count
        else:
            urls_dict[url] += count

    sorted_urls = sorted(urls_dict.items(), key=lambda x: x[1], reverse=True)

    return sorted_urls

def main():
