    chrome_history_file = None
    for file in os.listdir(chrome_local_storage_path):
        if re.search(r'^https?://.+?History', file):
            chrome_history_file = os.path.join(chrome_local_storage_path, file)
            break

    if chrome_history_file:
        browser_history = read_chrome_history(chrome_history_file)
        frequent_urls = analyze_browser_history(browser_history)

        for url, count in frequent_urls:
